Here is the commit message:
drm/tegra: Fix gpiod_get_from_of_node() regression

That function now returns ERR_PTR instead of NULL if "hpd-gpio" is not
present in device-tree. The offending patch missed to adapt the Tegra's
DRM driver for the API change.

Fixes: 025bf37725f1 ("gpio: Fix return value mismatch of function gpiod_get_from_of_node()")
Signed-off-by: Dmitry Osipenko <digetx@gmail.com>
Acked-by: Jon Hunter <jonathanh@nvidia.com>
Signed-off-by: Thierry Reding <treding@nvidia.com>

Here is the root cause:
The bug was caused by a change in the return value of the `gpiod_get_from_of_node()` function, which now returns `ERR_PTR` instead of `NULL` when the "hpd-gpio" is not present in the device tree. The Tegra DRM driver did not adapt to this change, leading to incorrect error handling and potential crashes when the GPIO was not defined.

Here is the patch:

 int tegra_output_probe(struct tegra_output *output)
 {
 	struct device_node *ddc, *panel;
 	unsigned long flags;
 	int err, size;

 	if (!output->of_node)
 		output->of_node = output->dev->of_node;

 	panel = of_parse_phandle(output->of_node, "nvidia,panel", 0);
 	if (panel) {
 		output->panel = of_drm_find_panel(panel);
 		if (IS_ERR(output->panel))
 			return PTR_ERR(output->panel);

 		of_node_put(panel);
 	}

 	output->edid = of_get_property(output->of_node, "nvidia,edid", &size);

 	ddc = of_parse_phandle(output->of_node, "nvidia,ddc-i2c-bus", 0);
 	if (ddc) {
 		output->ddc = of_find_i2c_adapter_by_node(ddc);
 		if (!output->ddc) {
 			err = -EPROBE_DEFER;
 			of_node_put(ddc);
 			return err;
 		}

 		of_node_put(ddc);
 	}

 	output->hpd_gpio = devm_gpiod_get_from_of_node(output->dev,
 						       output->of_node,
 						       "nvidia,hpd-gpio", 0,
 						       GPIOD_IN,
 						       "HDMI hotplug detect");
-	if (IS_ERR(output->hpd_gpio))
-		return PTR_ERR(output->hpd_gpio);
+	if (IS_ERR(output->hpd_gpio)) {
+		if (PTR_ERR(output->hpd_gpio) != -ENOENT)
+			return PTR_ERR(output->hpd_gpio);
+
+		output->hpd_gpio = NULL;
+	}

 	if (output->hpd_gpio) {
 		err = gpiod_to_irq(output->hpd_gpio);
 		if (err < 0) {
 			dev_err(output->dev, "gpiod_to_irq(): %d\n", err);
 			return err;
 		}

 		output->hpd_irq = err;

 		flags = IRQF_TRIGGER_RISING | IRQF_TRIGGER_FALLING |
 			IRQF_ONESHOT;

 		err = request_threaded_irq(output->hpd_irq, NULL, hpd_irq,
 					   flags, "hpd", output);
 		if (err < 0) {
 			dev_err(output->dev, "failed to request IRQ#%u: %d\n",
 				output->hpd_irq, err);
 			return err;
 		}

 		output->connector.polled = DRM_CONNECTOR_POLL_HPD;

 		/*
 		 * Disable the interrupt until the connector has been
 		 * initialized to avoid a race in the hotplug interrupt
 		 * handler.
 		 */
 		disable_irq(output->hpd_irq);
 	}

 	output->cec = cec_notifier_get(output->dev);
 	if (!output->cec)
 		return -ENOMEM;

 	return 0;
 }



